script:
frappe.ui.form.on('Employee Checkin', {
    refresh(frm) {
        frm.add_custom_button("Get Employyee checkIn Data", () => {
            frappe.call({
                method: "tgbchr.api.process_raw_attendance",
                args: {},
                callback: function(response) {
                    if (response.message) {

                        frappe.msgprint(response.message);
                    } else {
                        frappe.msgprint(__('No data received from the server'));
                    }
                },
                error: function(error) {
                    frappe.msgprint(__('Error occurred while fetching data: ') + error.message);
                }
            });
        }).addClass("btn-warning").css({"background-color": "#171717", "color": "white"});
    },
})

frappe.ui.form.on('Raw Attendance Data', {
    refresh(frm) {
        frm.add_custom_button("Get Attendance Data", () => {
            frappe.call({
                method: "tgbchr.api.get_and_update_attendance",
                args: {},
                callback: function(response) {
                    if (response.message) {

                        frappe.msgprint(response.message);
                    } else {
                        frappe.msgprint(__('No data received from the server'));
                    }
                },
                error: function(error) {
                    frappe.msgprint(__('Error occurred while fetching data: ') + error.message);
                }
            });
        }).addClass("btn-warning").css({"background-color": "#171717", "color": "white"});
    },
})

frappe.ui.form.on('Attendance Request', {
    before_submit: function(frm) {
        const user = frappe.session.user;
        const approver = frm.doc.custom_employers_approver;

        if (user !== approver) {
            frappe.msgprint("This request must be submitted by your designated approver. Kindly contact your approver for submission.");
            frappe.validated = false;   // stop submit
        }
    }
});
